<template><section class="dm-view" aria-label="Agent conversation messages"><header><div><span class="message-mark">↗</span><h3>Agent messages</h3><small>{{ replaying?'Saved discussion replay':running?'Recorded updates':'Saved conversation' }}</small></div><button @click="$emit('toggle-follow')">{{ paused?(replaying?'Resume replay':running?'Follow updates':'Follow messages'):(replaying?'Pause replay':'Pause following') }}</button></header><div class="dm-filter"><select :value="focus" aria-label="Message participant" @change="$emit('select',$event.target.value)"><option value="">All conversations</option><option v-for="person in people" :key="person.id" :value="person.id">{{ person.label }}</option></select><span>{{ paused?'Following paused':replaying?'Replay · no AI requests':'Read recorded messages' }}</span></div><div ref="scrollEl" class="dm-scroll" @wheel="$emit('hold')" @pointerdown="$emit('hold')"><TransitionGroup name="bubble" tag="ol"><li v-for="event in filtered" :key="event.replayKey||event.id" :class="[relationTone(event),{reply:event.kind.includes('reply')||event.kind.includes('response'),spotlight:selectedEventId===event.id}]"><span class="avatar">{{ initials(name(event.author)) }}</span><div class="message-content"><div class="message-meta"><button class="message-link" @click="$emit('message',event)">{{ name(event.author) }}<span v-if="event.recipients.length"> → {{ event.recipients.map(name).join(', ') }}</span></button><time :datetime="event.at?new Date(event.at).toISOString():undefined" :title="event.at?new Date(event.at).toLocaleString():'Time not recorded'">{{ event.reused?'Earlier · ':'' }}{{ event.at?new Date(event.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Time not recorded' }}</time></div><p class="recipient">{{ event.kind.replaceAll('_',' ') }}<span v-if="event.replay"> · saved replay</span></p><div class="chat-bubble"><p>{{ excerpt(event.text) }}</p><details v-if="event.text.length>360" @toggle="$emit('hold')"><summary>Read full message</summary><p>{{ event.text }}</p></details></div></div></li></TransitionGroup><p v-if="!filtered.length" class="dm-empty">{{ replaying?'Replay is beginning.':'No recorded messages for this selection yet.' }}</p></div><footer><span>{{ focus?'Authored and received messages':'Individual agent conversations' }}</span><button @click="$emit('discussion',focusLens)">Full discussion ↗</button></footer></section></template>
<script setup>
import {computed,ref,watch,nextTick} from 'vue'
import {relationTone} from '../utils/agentInteraction.mjs'
import {participantMessages} from '../utils/playground.mjs'
const props=defineProps({events:Array,people:Array,focus:String,paused:Boolean,replaying:Boolean,running:Boolean,selectedEventId:String})
defineEmits(['select','hold','toggle-follow','discussion','message'])
const scrollEl=ref(null),filtered=computed(()=>participantMessages(props.events,props.focus))
const name=id=>props.people.find(p=>p.id===id)?.label||id
const excerpt=text=>text.length>360?text.slice(0,357).replace(/\s+\S*$/,'')+'…':text
const initials=name=>name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()
const focusLens=computed(()=>props.people.find(p=>p.id===props.focus)?.lens||'specialists')
watch(()=>[props.events.length,props.focus,props.paused],async()=>{await nextTick();if(!props.paused&&scrollEl.value)scrollEl.value.scrollTop=scrollEl.value.scrollHeight},{immediate:true})
</script>
<style scoped>
.dm-view{border:1px solid #e0e7ef;border-radius:9px;background:white;overflow:hidden;min-width:0}.dm-view>header{padding:13px 15px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #edf1f6}.dm-view header>div{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.message-mark{width:25px;height:25px;background:#fff1e8;color:#ed5f1b;border-radius:7px;display:grid;place-items:center}.dm-view h3{font-size:14px;margin:0;font-weight:600}.dm-view header small{font-size:10px;color:#8795a7}.dm-view button{border:0;background:none;color:#a73508;font-size:11px;cursor:pointer;padding:0}.dm-filter{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 15px;background:#fcfcfd}.dm-filter select{font:11px inherit;font-size:11px;border:1px solid #e0e7ef;padding:6px 8px;border-radius:5px;background:white;color:#5c718b;max-width:65%}.dm-filter>span{font-size:9px;color:#92a0b1}.dm-scroll{max-height:310px;min-height:140px;overflow:auto;overscroll-behavior:contain;padding:8px 15px 15px}.dm-scroll ol{list-style:none;margin:0;padding:0}.dm-scroll li{display:flex;gap:9px;align-items:start;margin:12px 0;min-width:0}.avatar{width:29px;height:29px;border-radius:50%;flex:0 0 29px;display:grid;place-items:center;background:#fff1e8;color:#a7653e;font-size:9px;border:1px solid #f6e2d4}.reply .avatar{background:#edf5ff;color:#6285b0;border-color:#dbe8f9}.message-content{min-width:0;flex:1}.message-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;line-height:1.5}.message-meta b{font-size:11px;font-weight:550;color:#3c506a}.message-meta time{font-size:9px;color:#94a0b0}.recipient{font-size:9px;color:#8a9aad;margin:3px 0 6px;line-height:1.5;overflow-wrap:anywhere}.chat-bubble{background:#fff9f5;border:1px solid #f2e8df;border-radius:0 10px 10px 10px;padding:10px 12px;font-size:12px;line-height:1.65;color:#586d87;overflow-wrap:anywhere;white-space:pre-wrap}.chat-bubble>p{margin:0}.chat-bubble details{white-space:normal;margin-top:7px}.chat-bubble summary{font-size:10px;color:#a86940;cursor:pointer}.chat-bubble details p{margin:8px 0 0;white-space:pre-wrap}.reply .chat-bubble{background:#f6faff;border-color:#e5edf8}.dm-view footer{padding:10px 15px;border-top:1px solid #edf1f6;font-size:10px;color:#8b99ac;display:flex;justify-content:space-between;gap:10px}.dm-empty{font-size:12px;color:#8d9aad;line-height:1.7}.bubble-enter-active{transition:opacity .35s,transform .35s}.bubble-enter-from{opacity:0;transform:translateY(9px)}@media(max-width:620px){.dm-scroll{max-height:290px}.dm-filter>span{display:none}.dm-filter select{max-width:100%;width:100%}}@media(prefers-reduced-motion:reduce){.bubble-enter-active{transition:none}}

.dm-scroll{scrollbar-width:thin;scrollbar-color:#cbd7e4 transparent}.dm-scroll::-webkit-scrollbar{width:5px;height:5px}.dm-scroll::-webkit-scrollbar-track{background:transparent}.dm-scroll::-webkit-scrollbar-thumb{background:#cbd7e4;border-radius:5px}

.message-link{font-weight:550!important;font-size:11px!important;text-align:left;color:#3b526d!important;line-height:1.5}.message-link span{font-weight:400;color:#8192a5}.spotlight .chat-bubble{border-color:#e9bfa3;box-shadow:0 0 0 2px #fff0e5}.reply.spotlight .chat-bubble{border-color:#b3d1ee;box-shadow:0 0 0 2px #edf5ff}.dm-view footer{background:#fcfdfe}

.disagreement .chat-bubble{background:#faf5ff;border-color:#dcc9ef}.disagreement .avatar{background:#f2e7fc;color:#885aaa}
</style>
